// Rule L9: the HLSL of a 1.x function that returns nothing returns its first `out`, and a 1.x body calls it that way --
// as a value, or passing that `out` as well. Migrated, such a function is declared returning it; a Namespace function,
// a library's entry point, keeps its `out`s, and the body that read one as a value calls an adapter.

/// @custom
float MrHash(float x)
{
    float result = (float)0;
    result = frac(sin(x) * 43758.5453);
    return result;
}

// Two outputs: the first is returned, the second stays an `out`.
/// @custom
float MrCell(float2 p, out float2 id)
{
    float dist = (float)0;
    id = floor(p);
    dist = length(frac(p) - 0.5) + MrHash(id.x + id.y * 57.0) * 0.001;
    return dist;
}

/// @custom
float4 MrSample(Texture2D tex, float2 uv)
{
    float4 color = (float4)0;
    color = Texture2DSample(tex, texSampler, uv);
    return color;
}

/// @custom
float MrUse(Texture2D tex, float2 p)
{
    float value = (float)0;
    float d;
    float2 cell;
    // every output passed: d is what MrCell returns
    d = MrCell(p, cell);
    float4 c = MrSample(tex, p);
    float w;
    value = d + c.r + MrSpace_Tint_tinted(c.rgb, w).r * w;
    return value;
}

/// @custom
/// @name MrSpace::Tint
void MrSpace_Tint(float3 color, out float3 tinted, out float weight)
{
    tinted = color * 0.5;
    weight = 1.0;
}

// MrSpace::Tint as a 1.x body read it: its first 'out', returned.
/// @custom
float3 MrSpace_Tint_tinted(float3 color, out float weight)
{
    float3 tinted = (float3)0;
    MrSpace_Tint(color, tinted, weight);
    return tinted;
}
